		sceVu0UnitMatrix(inverse.m_matrix);
		Vu0MatrixInverseWithUniformScale(&inverse, CStack::m_top);
		di->m_MTail = di->m_Tail;
		inverse.Transform(&di->m_MTail, 1);
		di->m_MTip = di->m_Tip;
		inverse.Transform(&di->m_MTip, 1);

