		tip.x = di->m_MTip.x;
		tip.y = di->m_MTip.y;
		tip.z = di->m_MTip.z;
		tip.w = 1.0f;
		CPnt4D tail;
		tail.x = di->m_MTail.x;
		tail.y = di->m_MTail.y;
		tail.z = di->m_MTail.z;
		tail.w = 1.0f;
